// src/components/ui/NavItem.jsx

export default function NavItem({ icon, label, active, onClick, badge, id }) {
  return (
    <button
      onClick={() => onClick(id)}
      style={{
        display: "flex", alignItems: "center", gap: 10, padding: "9px 12px",
        borderRadius: 8, cursor: "pointer", width: "100%", textAlign: "left",
        background: active ? "rgba(255,255,255,0.13)" : "transparent",
        color: active ? "#fff" : "rgba(255,255,255,0.6)",
        border: active ? "1px solid rgba(255,255,255,0.18)" : "1px solid transparent",
        fontSize: 13.5, fontWeight: active ? 500 : 400, transition: "all 0.14s", position: "relative",
      }}
    >
      <span style={{ fontSize: 16, width: 22, textAlign: "center", flexShrink: 0 }}>{icon}</span>
      <span style={{ flex: 1 }}>{label}</span>
      {badge && (
        <span style={{ background: "#b83232", color: "#fff", borderRadius: 10, fontSize: 10, padding: "1px 5px", minWidth: 16, textAlign: "center" }}>
          {badge}
        </span>
      )}
    </button>
  );
}
